// Orca reports WSL workspaces as UNC paths, while the plugin worker always runs on the desktop host.
// Entire has to run where the repo and its login live, so each workspace path maps to a host.

const WSL_UNC = /^\\\\wsl(?:\.localhost|\$)\\([^\\]+)(\\.*)?$/i

export function workspaceHost(workspacePath) {
  const match = WSL_UNC.exec(workspacePath.replaceAll('/', '\\'))
  if (!match) return { kind: 'local', path: workspacePath }
  return { kind: 'wsl', distro: match[1], path: (match[2] ?? '\\').replaceAll('\\', '/') }
}

export function entireCommand(host, args) {
  if (host.kind === 'wsl') {
    // A login shell puts ~/.local/bin on PATH; "$@" passes each argument through without re-parsing.
    return {
      command: 'wsl.exe',
      args: ['-d', host.distro, '--cd', host.path, '-e', 'bash', '-lc', 'exec entire "$@"', 'entire', ...args]
    }
  }
  return { command: 'entire', args, cwd: host.path }
}

import test from 'node:test'
import assert from 'node:assert/strict'
import { connectionNotice } from '../src/worker/doctor.mjs'

test('a report without failures is a connected notice, without the host API line', () => {
  const notice = connectionNotice(
    ['Orca host API 1.0 · Node v24 on win32', '✓ main on main → C:\\repo (via terminal)', '· Trail: no trail'].join('\n')
  )
  assert.equal(notice.title, 'Entire: connected')
  assert.equal(notice.body, '✓ main on main → C:\\repo (via terminal)\n· Trail: no trail')
})

test('any failed step makes it a problem, and the body fits a notification', () => {
  const notice = connectionNotice(`Orca host API 1.0\n✗ Repo: ${'x'.repeat(2000)}`)
  assert.equal(notice.title, 'Entire: connection problem')
  assert.equal(notice.body.length, 1000)
})

import test from 'node:test'
import assert from 'node:assert/strict'
import { matchWorktrees, shortBranch } from '../src/worker/workspace.mjs'

test("Orca CLI refs compare with readContext's short branch names", () => {
  assert.equal(shortBranch('refs/heads/feat/trails'), 'feat/trails')
  assert.equal(shortBranch('main'), 'main')
  assert.equal(shortBranch(''), '')
})

test('branch and name must both match, and archived workspaces never do', () => {
  const worktrees = [
    { path: 'a', branch: 'refs/heads/main', displayName: 'main' },
    { path: 'b', branch: 'refs/heads/main', displayName: 'api' },
    { path: 'c', branch: 'refs/heads/main', displayName: 'main', isArchived: true },
    { path: 'd', branch: '', displayName: 'main' }
  ]
  const matches = matchWorktrees(worktrees, { branch: 'main', displayName: 'main' })
  assert.deepEqual(
    matches.map((worktree) => worktree.path),
    ['a']
  )
})

import { existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { desktopEnv, run } from './process.mjs'

// The worker runs inside Orca's own binary (ELECTRON_RUN_AS_NODE), so Orca's CLI ships beside it.
// Verified on Windows; check the layout before relying on it on macOS.
export function orcaCliPath(execPath = process.execPath, platform = process.platform) {
  const cli = join(dirname(execPath), 'resources', 'bin', platform === 'win32' ? 'orca.exe' : 'orca')
  return existsSync(cli) ? cli : null
}

export async function orcaCli(args, { signal } = {}) {
  const cli = orcaCliPath()
  if (!cli) throw new Error(`Orca CLI not found beside ${process.execPath}`)
  const name = `orca ${args.slice(0, 2).join(' ')}`
  const { code, stdout } = await run(cli, [...args, '--json'], { env: desktopEnv(), signal })
  let reply
  try {
    reply = JSON.parse(stdout)
  } catch {
    throw new Error(`${name} printed no JSON (exit ${code})`)
  }
  if (!reply.ok) throw new Error(`${name}: ${reply.error?.message ?? 'failed'}`)
  return reply.result
}

