orca.events.on('agent.status.changed', (event) => {
  if ((event.mainAgent?.state ?? event.state) !== 'done') return
  clearTimeout(timer)
  timer = setTimeout(() => {
    queue = queue.then(() => refresh()).catch((error) => console.error(`Refresh failed: ${error.message}`))
  }, AGENT_SETTLE_MS)
