import test from 'node:test'
import assert from 'node:assert/strict'
import { readFile } from 'node:fs/promises'
import { trailSummary } from '../src/worker/trail.mjs'

// `entire trail show --json` for trail #1 on plugin-scaffold, right after it was created.
const fixture = JSON.parse(await readFile(new URL('./fixtures/trail-show.json', import.meta.url), 'utf8'))

test('a trail keeps what the panel shows and drops ids and accounts', () => {
  const summary = trailSummary(fixture)
  assert.deepEqual(
    { number: summary.number, title: summary.title, status: summary.status, type: summary.type, priority: summary.priority },
    { number: 1, title: 'Entire for Orca: plugin scaffold and panel', status: 'open', type: 'feature', priority: null }
  )
  assert.deepEqual(summary.changes, [{ repository: 'orca-entire-extension', branch: 'plugin-scaffold', status: 'open', current: true }])
  assert.ok(!JSON.stringify(summary).includes(fixture.authorAccountId))
})

test("the current change's gates come with their reasons and counts", () => {
  const { merge } = trailSummary(fixture)
  assert.equal(merge.mergeable, false)
  assert.equal(merge.conflicts, null)
  assert.deepEqual(merge.checks, [])
  assert.deepEqual(merge.gates, [
    { key: 'approvals', blocking: true, status: 'failed', rationale: 'No reviewers have approved this trail', progress: '0/1' },
    { key: 'findings', blocking: true, status: 'pending', rationale: 'Gate has not been evaluated yet', progress: null },
    { key: 'up_to_date', blocking: true, status: 'passed', rationale: 'Up to date', progress: null }
  ])
})

test('a trail without changes or mergeability still summarizes', () => {
  const summary = trailSummary({ number: 2, title: 'Intent only', status: 'open', body: 'x'.repeat(1000) })
  assert.deepEqual(summary.changes, [])
  assert.equal(summary.merge, null)
  assert.equal(summary.body.length, 400)
})

