// What the panel shows of `entire trail show --json` (shape in test/fixtures/trail-show.json): the
// trail, the repositories and branches it spans, and the merge gates of the change this branch is.
const BODY_LIMIT = 400

export function trailSummary(trail) {
  const changes = Array.isArray(trail.changes) ? trail.changes : []
  const current = changes.find((change) => change.current) ?? changes.find((change) => change.mergeability) ?? null
  return {
    number: trail.number ?? null,
    title: trail.title ?? '',
    status: trail.status ?? null,
    type: trail.type ?? null,
    priority: trail.priority && trail.priority !== 'none' ? trail.priority : null,
    body: typeof trail.body === 'string' ? trail.body.slice(0, BODY_LIMIT) : '',
    changes: changes.map((change) => ({
      repository: change.repository ?? '',
      branch: change.branch ?? '',
      status: change.status ?? null,
      current: change === current
    })),
    merge: current?.mergeability ? mergeSummary(current.mergeability) : null
  }
}

function mergeSummary(mergeability) {
  return {
    mergeable: Boolean(mergeability.mergeable),
    conflicts: mergeability.conflict_status && mergeability.conflict_status !== 'clean' ? mergeability.conflict_status : null,
    // No fixture has a check run yet, so read the likely fields.
    checks: (mergeability.checks?.runs ?? []).map((run) => ({
      name: run.name ?? run.title ?? 'check',
      status: run.conclusion ?? run.status ?? 'unknown'
    })),
    gates: (mergeability.gates ?? []).map((gate) => ({
      key: gate.gate_key ?? gate.gate_type ?? 'gate',
      blocking: Boolean(gate.blocking),
      status: gate.status ?? 'unknown',
      rationale: gate.rationale ?? '',
      progress: gateProgress(gate)
    }))
  }
}

// A short count where a gate has one, such as approvals 0/1.
function gateProgress({ gate_type: type, value, finding_count: findings }) {
  if (type === 'approvals' && value) return `${value.approved}/${value.required}`
  if (type === 'findings' && typeof findings === 'number') return String(findings)
  if (type === 'up_to_date' && value?.behind_by > 0) return `${value.behind_by} behind`
  return null
}

import test from 'node:test'
import assert from 'node:assert/strict'
import { readFile } from 'node:fs/promises'
import { trailSummary } from '../src/worker/trail.mjs'

// `entire trail show --json` for trail #1 on plugin-scaffold, right after it was created.
const fixture = JSON.parse(await readFile(new URL('./fixtures/trail-show.json', import.meta.url), 'utf8'))

test('a trail keeps what the panel shows and drops ids and accounts', () => {
  const summary = trailSummary(fixture)
  assert.deepEqual(
    { number: summary.number, title: summary.title, status: summary.status, type: summary.type, priority: summary.priority },
    { number: 1, title: 'Entire for Orca: plugin scaffold and panel', status: 'open', type: 'feature', priority: null }
  )
  assert.deepEqual(summary.changes, [{ repository: 'orca-entire-extension', branch: 'plugin-scaffold', status: 'open', current: true }])
  assert.ok(!JSON.stringify(summary).includes(fixture.authorAccountId))
})

test("the current change's gates come with their reasons and counts", () => {
  const { merge } = trailSummary(fixture)
  assert.equal(merge.mergeable, false)
  assert.equal(merge.conflicts, null)
  assert.deepEqual(merge.checks, [])
  assert.deepEqual(merge.gates, [
    { key: 'approvals', blocking: true, status: 'failed', rationale: 'No reviewers have approved this trail', progress: '0/1' },
    { key: 'findings', blocking: true, status: 'pending', rationale: 'Gate has not been evaluated yet', progress: null },
    { key: 'up_to_date', blocking: true, status: 'passed', rationale: 'Up to date', progress: null }
  ])
})

test('a trail without changes or mergeability still summarizes', () => {
  const summary = trailSummary({ number: 2, title: 'Intent only', status: 'open', body: 'x'.repeat(1000) })
  assert.deepEqual(summary.changes, [])
  assert.equal(summary.merge, null)
  assert.equal(summary.body.length, 400)
})

