# Runs one harness refresh and records every process it starts and every window that becomes visible.
param([string]$Repo, [string[]]$HarnessArgs)

Add-Type @'
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text;
public static class Windows {
  delegate bool EnumProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] static extern bool EnumWindows(EnumProc cb, IntPtr lParam);
  [DllImport("user32.dll")] static extern bool IsWindowVisible(IntPtr hWnd);
  [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint pid);
  [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern int GetClassName(IntPtr hWnd, StringBuilder s, int n);
  [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern int GetWindowText(IntPtr hWnd, StringBuilder s, int n);
  public static List<string> Visible() {
    var list = new List<string>();
    EnumWindows((h, l) => {
      if (!IsWindowVisible(h)) return true;
      uint pid; GetWindowThreadProcessId(h, out pid);
      var c = new StringBuilder(256); GetClassName(h, c, 256);
      var t = new StringBuilder(256); GetWindowText(h, t, 256);
      list.Add(h.ToInt64() + "|" + pid + "|" + c + "|" + t);
      return true;
    }, IntPtr.Zero);
    return list;
  }
}
'@

$before = @{}; foreach ($w in [Windows]::Visible()) { $before[$w.Split('|')[0]] = $true }
$known = @{}; foreach ($p in Get-Process) { $known[$p.Id] = $true }
$started = Get-Date
$harness = Start-Process -FilePath node -ArgumentList (@('scripts/orca-harness/launch.mjs') + $HarnessArgs) -WorkingDirectory $Repo -NoNewWindow -PassThru -RedirectStandardOutput "$PSScriptRoot\watch-harness.out"
$procs = @{}; $windows = @{}
$stopAt = $null
