# Runs one harness refresh and prints the tree of processes it starts, from WMI creation events.
param([string]$Repo, [string[]]$HarnessArgs)

$events = [System.Collections.Concurrent.ConcurrentQueue[object]]::new()
$sub = Register-CimIndicationEvent -Query "SELECT * FROM __InstanceCreationEvent WITHIN 0.05 WHERE TargetInstance ISA 'Win32_Process'" -SourceIdentifier ProcTrace -MessageData $events -Action {
  $p = $Event.SourceEventArgs.NewEvent.TargetInstance
  $Event.MessageData.Enqueue([pscustomobject]@{ At = Get-Date; Id = [int]$p.ProcessId; Parent = [int]$p.ParentProcessId; Name = $p.Name; Cmd = $p.CommandLine })
}
Start-Sleep -Milliseconds 500
$started = Get-Date
$harness = Start-Process -FilePath node -ArgumentList (@('scripts/orca-harness/launch.mjs') + $HarnessArgs) -WorkingDirectory $Repo -NoNewWindow -PassThru -RedirectStandardOutput "$PSScriptRoot\trace-harness.out"
$harness.WaitForExit()
Start-Sleep -Seconds 4
Unregister-Event -SourceIdentifier ProcTrace
$all = @{}; foreach ($e in $events.ToArray()) { $all[$e.Id] = $e }
$children = @{}; foreach ($e in $all.Values) { if (-not $children[$e.Parent]) { $children[$e.Parent] = @() }; $children[$e.Parent] += $e }
function Show($id, $depth) {
  foreach ($c in ($children[$id] | Sort-Object At)) {
    $cmd = if ($c.Cmd) { $c.Cmd -replace '\s+', ' ' } else { '' }
    "{0,5:N2}s {1}{2}#{3}  {4}" -f ($c.At - $started).TotalSeconds, ('  ' * $depth), $c.Name, $c.Id, $cmd.Substring(0, [Math]::Min(150, $cmd.Length))
    Show $c.Id ($depth + 1)
  }
}
"== tree under the harness (node#$($harness.Id))"
Show $harness.Id 0
"== processes whose parent was not seen starting (top 40 by time)"
$all.Values | Where-Object { -not $all[$_.Parent] -and $_.Id -ne $harness.Id -and $_.At -ge $started } | Sort-Object At | Select-Object -First 40 | ForEach-Object {
  $cmd = if ($_.Cmd) { $_.Cmd -replace '\s+', ' ' } else { '' }
  "{0,5:N2}s {1}#{2} (parent #{3})  {4}" -f ($_.At - $started).TotalSeconds, $_.Name, $_.Id, $_.Parent, $cmd.Substring(0, [Math]::Min(150, $cmd.Length))
}

