# Records, for a while, every new process (with its parent chain) and every window that becomes visible.
param([int]$Seconds = 45)

Add-Type @'
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text;
public static class Win {
  delegate bool EnumProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] static extern bool EnumWindows(EnumProc cb, IntPtr lParam);
  [DllImport("user32.dll")] static extern bool IsWindowVisible(IntPtr hWnd);
  [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint pid);
  [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern int GetClassName(IntPtr hWnd, StringBuilder s, int n);
  [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern int GetWindowText(IntPtr hWnd, StringBuilder s, int n);
  public static List<string> Visible() {
    var list = new List<string>();
    EnumWindows((h, l) => {
      if (!IsWindowVisible(h)) return true;
      uint pid; GetWindowThreadProcessId(h, out pid);
      var c = new StringBuilder(256); GetClassName(h, c, 256);
      var t = new StringBuilder(256); GetWindowText(h, t, 256);
      list.Add(h.ToInt64() + "|" + pid + "|" + c + "|" + t);
      return true;
    }, IntPtr.Zero);
    return list;
  }
}
'@

$events = [System.Collections.Concurrent.ConcurrentQueue[object]]::new()
Register-CimIndicationEvent -Query "SELECT * FROM __InstanceCreationEvent WITHIN 0.05 WHERE TargetInstance ISA 'Win32_Process'" -SourceIdentifier IdleTrace -MessageData $events -Action {
  $p = $Event.SourceEventArgs.NewEvent.TargetInstance
  $Event.MessageData.Enqueue([pscustomobject]@{ At = Get-Date; Id = [int]$p.ProcessId; Parent = [int]$p.ParentProcessId; Name = $p.Name; Cmd = $p.CommandLine })
} | Out-Null
$names = @{}; foreach ($c in Get-CimInstance Win32_Process) { $names[[int]$c.ProcessId] = $c.Name }
$before = @{}; foreach ($w in [Win]::Visible()) { $before[$w.Split('|')[0]] = $true }
$started = Get-Date; $windows = @{}
while (((Get-Date) - $started).TotalSeconds -lt $Seconds) {
  foreach ($w in [Win]::Visible()) { $f = $w.Split('|'); if (-not $before[$f[0]] -and -not $windows[$f[0]]) { $windows[$f[0]] = [pscustomobject]@{ At = Get-Date; Pid = [int]$f[1]; Class = $f[2]; Title = $f[3] } } }
  Start-Sleep -Milliseconds 50
}
Start-Sleep -Seconds 1
Unregister-Event -SourceIdentifier IdleTrace
$all = @{}; foreach ($e in $events.ToArray()) { $all[$e.Id] = $e; $names[$e.Id] = $e.Name }
function Chain($id) { $parts = @(); $seen = 0; while ($all[$id] -and $seen -lt 8) { $parts += "$($all[$id].Name)#$id"; $id = $all[$id].Parent; $seen++ }; $parts += "$($names[$id])#$id"; [array]::Reverse($parts); $parts -join ' > ' }
"== $($windows.Count) windows became visible in $Seconds s"
$windows.Values | Sort-Object At | ForEach-Object { "{0,5:N1}s  {1,-30} {2,-28} {3}" -f ($_.At - $started).TotalSeconds, $_.Class, $_.Title, (Chain $_.Pid) }
"== processes started: $($all.Count); by root of chain"
$roots = @{}
foreach ($e in $all.Values) { $id = $e.Id; $n = 0; while ($all[$all[$id].Parent] -and $n -lt 10) { $id = $all[$id].Parent; $n++ }; $root = "$($names[$all[$id].Parent])#$($all[$id].Parent) > $($all[$id].Name)"; $roots[$root] = 1 + [int]$roots[$root] }
$roots.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First 15 | ForEach-Object { "{0,4}  {1}" -f $_.Value, $_.Key }
"== analytics children"
$all.Values | Where-Object { $_.Cmd -match '__send_analytics' } | Sort-Object At | ForEach-Object { "{0,5:N1}s  {1}" -f ($_.At - $started).TotalSeconds, (Chain $_.Id) }
"== entire processes"
$all.Values | Where-Object { $_.Name -eq 'entire.exe' -and $_.Cmd -notmatch '__send_analytics' } | Sort-Object At | ForEach-Object { $cmd = ($_.Cmd -replace '\s+', ' '); "{0,5:N1}s  {1}  [{2}]" -f ($_.At - $started).TotalSeconds, $cmd.Substring(0, [Math]::Min(90, $cmd.Length)), (Chain $_.Parent) }

