/* Trail cards, after Entire's web view. */
.card {
  margin: 4px 6px 8px;
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) + 2px);
  background: var(--card);
  overflow: hidden;
}
.pad {
  padding: 8px 10px;
}
.spread {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}
.spread.gap {
  margin: 6px 0;
}
.tags {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}
.tag {
  min-width: 0;
  padding: 0 6px;
  border: 1px solid var(--border);
  border-radius: 4px;
  font-family: var(--mono);
  font-size: 11px;
  line-height: 18px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.diff {
  flex: none;
  font-family: var(--mono);
  font-size: 11px;
  color: var(--muted);
}
.plus {
  color: var(--ok);
}
.minus {
  color: var(--bad);
}
.card-title {
  font-weight: 600;
}
.card .name {
  font-weight: 600;
}
.card .about {
  margin-top: 2px;
  font-size: 11px;
  color: var(--muted);
}
.verdict {
  font-weight: 600;
  color: var(--tone, var(--muted));
}
.bar {
  display: flex;
  gap: 3px;
  margin: 6px 0 4px;
}
.bar span {
