  var where = add(el('div', 'spread'), add(el('div', 'tags'), value.repository ? titled(el('span', 'tag', value.repository), value.repository) : null, value.change ? el('span', 'tag', '#' + value.change) : null), el('span', 'meta clip', who))
  var branches = add(el('div', 'tags'), value.branch ? titled(el('span', 'tag', value.branch), value.branch) : null, value.base ? el('span', 'muted', '→') : null, value.base ? el('span', 'tag', value.base) : null)
  var diff = value.diff
    ? titled(add(el('span', 'diff'), el('span', 'plus', '+' + value.diff.additions), document.createTextNode(' / '), el('span', 'minus', '−' + value.diff.deletions)), plural(value.diff.files, 'file', 'files') + ' changed')
    : null
  var facts = [value.type && sentence(value.type), value.priority && sentence(value.priority) + ' priority', value.changes.length > 1 ? plural(value.changes.length, 'change', 'changes') : null]
  return add(
    el('div', 'card'),
    add(
      el('div', 'pad'),
      where,
      add(el('div', 'spread gap'), branches, diff),
      titled(el('div', 'name clamp', value.title || 'Untitled trail'), value.title),
      el('div', 'meta', facts.filter(Boolean).join(' · ')),
      value.body ? titled(el('div', 'about clamp', value.body), value.body) : null
    )
  )
}

// One bar segment per reviewer, filled once it finished, red when it found something blocking.
function reviewCard(review) {
  var verdict =
    review.status === 'passed'
      ? { tone: 'ok', text: 'Pass' }
      : review.status === 'failed'
        ? { tone: 'bad', text: 'Blocked' }
        : review.inFlight
          ? { tone: 'warn', text: 'Reviewing' }
          : { tone: '', text: 'Not run' }
  var bar = el('div', 'bar')
  var reviewers = review.reviewers.length ? review.reviewers : [null]
  reviewers.forEach(function (reviewer) {
    var kind = !reviewer ? '' : reviewer.blocking ? 'bad' : tone(reviewer.status)
    add(bar, titled(el('span', kind), reviewer && reviewer.name + ': ' + words(reviewer.status) + (reviewer.blocking ? ', ' + reviewer.blocking + ' blocking' : '')))
  })
  var counts = review.severity
  var found = counts.high + counts.medium + counts.low
  var detail = review.reviewers.length
    ? review.reviewers
        .map(function (reviewer) {
          return reviewer.name
        })
        .join(' · ') + (found ? ' · ' + [counts.high + ' high', counts.medium + ' medium', counts.low + ' low'].join(', ') : ' · nothing found')
    : 'No review has run on this version yet.'
  return add(el('div', 'card'), add(el('div', 'pad'), add(el('div', 'spread'), el('span', 'card-title', 'Code review'), el('span', 'verdict ' + verdict.tone, verdict.text)), bar, el('div', 'meta clip', detail)))
}

function mergeCard(value) {
  var state = mergeState(value)
  var card = add(el('div', 'card'), add(el('div', 'pad'), el('div', 'card-title', state.title), el('div', 'meta', state.line)))
  var merge = value.merge
  if (!merge) return card
  if (merge.conflicts) add(card, gateRow({ key: 'conflicts', status: 'failed', blocking: true, summary: words(merge.conflicts), people: [] }))
  merge.gates.forEach(function (gate) {
    add(card, gateRow(gate))
  })
  return card
}

function gateRow(gate) {
  var kind = gate.status === 'passed' ? 'ok' : gate.status === 'failed' ? (gate.blocking ? 'bad' : 'warn') : ''
  var people = el('span', 'people')
  ;(gate.people || []).slice(0, 4).forEach(function (login) {
    add(people, person(login))
  })
  return titled(add(el('div', 'gate ' + kind), statusIcon(kind), el('span', 'label', sentence(gate.key)), gate.summary ? el('span', 'meta clip', gate.summary) : el('span', 'clip'), people), gate.rationale)
}

function findingsList(findings) {
  var body = el('div')
  add(body, add(el('div', 'spread heading-row'), el('span', 'card-title', 'Findings'), el('span', 'meta', findings.open ? plural(findings.open, 'open', 'open') : 'None open')))
  if (!findings.items.length) return add(body, el('div', 'empty', findings.resolved || findings.dismissed ? findings.resolved + ' resolved, ' + findings.dismissed + ' dismissed.' : 'No findings on this version.'))
  findings.items.forEach(function (finding) {
    var severity = finding.severity ? el('span', 'sev ' + (finding.severity === 'high' ? 'bad' : finding.severity === 'medium' ? 'warn' : ''), finding.severity) : null
    var where = finding.file ? finding.file + (finding.line ? ':' + finding.line : '') : null
    add(body, titled(row(severity, el('div', 'clip', finding.title || 'Finding'), where ? el('div', 'meta clip mono', where) : null), finding.title))
  })
  return body
}

// The worker summarizes `entire trail show` and `entire trail finding list` (src/worker/trail.mjs).
function trail(entry) {
  var value = entry.data.trail
  if (!value) {
    var s = step(entry, 'trail')
    var missing = !s || /no discoverable|no trail/i.test(s.text)
    return titled(el('div', missing ? 'empty' : 'empty bad', missing ? 'No trail for this branch.' : s.text), s && s.text)
  }
  var body = add(el('div'), changeCard(value))
  if (value.merge && value.merge.review) add(body, reviewCard(value.merge.review))
  add(body, mergeCard(value))
  if (value.findings) add(body, findingsList(value.findings))
  value.changes
    .filter(function (change) {
      return !change.current
    })
    .forEach(function (change) {
      add(body, row(el('span', 'mark', '⎇'), el('div', 'clip', change.repository + ' · ' + change.branch), el('div', 'meta clip', words(change.status || ''))))
    })
  return body
}

