// Preview of the live panel data plus a trail #367 entry built from the fixtures (terminal id "t367").
import { readFile, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const repo = process.argv[2]
const load = (file) => import(pathToFileURL(join(repo, 'src', 'worker', file)).href)
const { readData, renderPanel } = await load('panel.mjs')
const { trailSummary } = await load('trail.mjs')
const fixture = async (name) => JSON.parse(await readFile(join(repo, 'test', 'fixtures', name), 'utf8'))

const data = readData(await readFile(join(repo, 'panel', 'entire.html'), 'utf8'))
const live = data.workspaces[0]
const trail = trailSummary(await fixture('trail-367-show.json'), {
  findings: await fixture('trail-367-findings.json'),
  diff: { files: 4, additions: 458, deletions: 20 }
})
const preview = {
  version: 1,
  workspaces: [
    live,
    { ...live, workspace: { ...live.workspace, name: 'endo', branch: 'fix/issue-610', terminals: ['t367'], where: 'WSL Ubuntu /home/peterc/endo.chat_backend' }, data: { ...live.data, trail } }
  ]
}
const shim = (await readFile(fileURLToPath(new URL('panel-preview.html', import.meta.url)), 'utf8')).split('</head>')[0] + '</head>\n'
await writeFile(fileURLToPath(new URL('panel-preview.html', import.meta.url)), shim + renderPanel(await readFile(join(repo, 'panel', 'template.html'), 'utf8'), preview))
console.log('preview ready')

