// Preview of the live panel data plus trail #358 (six resolved findings) as terminal "t358".
import { readFile, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const repo = process.argv[2]
const here = (name) => fileURLToPath(new URL(name, import.meta.url))
const load = (file) => import(pathToFileURL(join(repo, 'src', 'worker', file)).href)
const { readData, renderPanel } = await load('panel.mjs')
const { trailSummary } = await load('trail.mjs')
const json = async (path) => JSON.parse((await readFile(path, 'utf8')).replace(/^﻿/, ''))

const data = readData(await readFile(join(repo, 'panel', 'entire.html'), 'utf8'))
const live = data.workspaces[0]
const trail = trailSummary(await json(here('trail358/show.json')), { findings: await json(here('trail358/findings.json')), diff: { files: 6, additions: 214, deletions: 31 } })
const preview = {
  version: 1,
  workspaces: [live, { ...live, workspace: { ...live.workspace, name: 'jump-ins', branch: 'feat/jump-in-timing', terminals: ['t358'], where: 'WSL Ubuntu /home/peterc/ccw' }, data: { ...live.data, trail } }]
}
const shim = (await readFile(here('panel-preview.html'), 'utf8')).split('</head>')[0] + '</head>\n'
await writeFile(here('panel-preview.html'), shim + renderPanel(await readFile(join(repo, 'panel', 'template.html'), 'utf8'), preview))
console.log('preview ready')

