1	import { failureLine, runEntire } from './entire-cli.mjs'
2	import { diffStat, safeRef } from './git.mjs'
3	import { workspaceHost } from './hosts.mjs'
4	import { trailSummary } from './trail.mjs'
5	import { resolveFocusedWorkspace } from './workspace.mjs'
6	
7	const VERSION = { key: 'version', label: 'Entire CLI', args: ['--version'], parse: (out) => out.trim().split('\n')[0] }
8	
9	// Each step keeps its own outcome, so one failed call (a branch without a trail, say) hides nothing else.
10	const STEPS = [
11	  {
12	    key: 'status',
13	    label: 'Repo',
14	    args: ['status', '--json'],
15	    parse: JSON.parse,
16	    summarize: (status) =>
17	      status.enabled ? `enabled · agents: ${(status.agents ?? []).join(', ') || 'none'}` : 'Entire is not enabled here'
18	  },
19	  // A branch without a trail is normal, so this step reports instead of failing the check.
20	  {
21	    key: 'trail',
22	    label: 'Trail',
23	    args: ['trail', 'show', '--json'],
24	    optional: true,
25	    parse: JSON.parse,
26	    summarize: (trail) => `#${trail.number} ${trail.title} · ${trail.status}`
27	  },
28	  {
29	    key: 'checkpoints',
30	    label: 'Checkpoints',
31	    args: ['checkpoint', 'list', '--json'],
32	    parse: JSON.parse,
33	    summarize: (list) => `${list.length} on this branch`
34	  }
35	]
36	
37	// Fetched alongside the steps for the panel only: the connection check doesn't report them. Every status,
38	// so resolved findings and how they were fixed show too, as in Entire's web view.
39	const FINDINGS = {
40	  key: 'findings',
41	  label: 'Findings',
42	  args: ['trail', 'finding', 'list', '--status', 'any', '--freshness', 'any', '--json'],
43	  parse: JSON.parse
44	}
45	
46	// The panel keeps the newest checkpoints only.
47	const CHECKPOINT_LIMIT = 20
48	
49	// Everything the panel and "Entire: Check connection" show for the focused workspace.
50	export async function collectSnapshot(orca, { signal } = {}) {
51	  const snapshot = { at: new Date().toISOString(), workspace: null, problem: null, steps: [], data: {} }
52	
53	  let resolved
54	  try {
55	    resolved = await resolveFocusedWorkspace(orca, { signal })
56	  } catch (error) {
