}

// Entire's text is untrusted: escaping < > & keeps it from closing the script element it sits in.
export function embedData(data) {
  return JSON.stringify(data).replace(/[<>&]/g, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, '0')}`)
}

export function readData(html) {
  const match = DATA.exec(html)
  try {
    return match ? JSON.parse(match[2]) : null
  } catch {
    return null
  }
}

export function renderPanel(template, data) {
  if (!DATA.test(template)) throw new Error(`${TEMPLATE} has no entire-data script`)
  return template.replace(DATA, (_, open, _old, close) => `${open}${embedData(data)}${close}`)
}

// Same path, or a terminal they share.
function sameWorkspace(entry, other) {
  return (
    (entry.workspace.path && other.workspace.path === entry.workspace.path) ||
    other.workspace.terminals.some((id) => entry.workspace.terminals.includes(id)) ||
    (!other.workspace.path && other.workspace.name === entry.workspace.name && other.workspace.branch === entry.workspace.branch)
  )
}

// A newer entry replaces any for the same workspace.
export function mergeEntry(data, entry) {
  const others = (data?.workspaces ?? []).filter((other) => !sameWorkspace(entry, other))
  return { version: 1, workspaces: [entry, ...others].slice(0, MAX_WORKSPACES) }
}

// The entry the panel shows for a readContext result. Keep this the same as findEntry in
// panel/template.html: the worker uses it to tell whether the panel needs a read after a switch.
export function findShown(data, context) {
  const list = data?.workspaces ?? []
  const ids = context.terminals.map((terminal) => terminal.id)
  // A workspace keeps its terminals when it switches branch, so the branch has to match as well.
  const byTerminal = list.find((entry) => entry.workspace.branch === context.branch && entry.workspace.terminals.some((id) => ids.includes(id)))
  if (byTerminal) return byTerminal
  // Many repos share a name and branch such as main/main: only when terminals can't tell them apart
  // and exactly one entry matches.
  const byName = list.filter(
    (entry) =>
      !(ids.length > 0 && entry.workspace.terminals.length > 0) && entry.workspace.name === context.displayName && entry.workspace.branch === context.branch
  )
  return byName.length === 1 ? byName[0] : null
}

// When the panel's data for the focused workspace was read from Entire, in ms, or null if it has none.
export function shownAt(context, root = PLUGIN_ROOT) {
  let data
  try {
    data = readData(readFileSync(join(root, PANEL), 'utf8'))
  } catch {
    return null
  }
  const at = Date.parse(findShown(data, context)?.at)
  return Number.isFinite(at) ? at : null
}

// Whether the panel already shows this entry's data: only when it was read and how long Entire took differ.
export function shownAlready(data, entry) {
  const shown = (data?.workspaces ?? []).find((other) => sameWorkspace(entry, other))
  const comparable = (e) => JSON.stringify({ ...e, at: undefined, report: undefined, steps: e.steps?.map(({ ms, ...step }) => step) })
  return Boolean(shown) && comparable(shown) === comparable(entry)
}

// Commands, agent events and ↻ each refresh on their own, so updates take turns: two overlapping
// read-merge-writes would each start from the same old panel and one workspace would be lost.
let writes = Promise.resolve()

// Each write remounts the panel, which closes what the user opened and loses their scroll, so timed
// refreshes pass onlyIfChanged. ↻ never does: its spinner stops only when the panel remounts.
export function updatePanel(entry, { root = PLUGIN_ROOT, onlyIfChanged = false } = {}) {
  if (isInstalledCopy(root)) return Promise.resolve('installed copy')
  const update = writes.then(async () => {
    const target = join(root, PANEL)
    const [template, current] = await Promise.all([
      readFile(join(root, TEMPLATE), 'utf8'),
      readFile(target, 'utf8').catch(() => '')
    ])
    const data = readData(current)
    if (onlyIfChanged && shownAlready(data, entry)) return 'unchanged'
    await writeAtomically(target, renderPanel(template, mergeEntry(data, entry)))
    return 'updated'
  })
  writes = update.catch(() => {})
  return update
}

// Orca refuses a plugin whose panel entry is missing, so a fresh clone needs an empty panel first.
export async function ensurePanel(root = PLUGIN_ROOT) {
  const target = join(root, PANEL)
  if (existsSync(target)) return false
  await writeAtomically(target, renderPanel(await readFile(join(root, TEMPLATE), 'utf8'), null))
  return true
}

// Orca may read the panel at any moment; a rename never shows it half written. The temporary name
// carries the process id, so the harness and Orca's worker never share one.
async function writeAtomically(target, text) {
  const temporary = `${target}.${process.pid}.tmp`
  await writeFile(temporary, text)
  await rename(temporary, target)
}

// Orca forks this module in a Node worker on the desktop host and calls activate once.
import manifest from '../../orca-plugin.json' with { type: 'json' }
import { connectionNotice, connectionReport } from './doctor.mjs'
import { contextKey, createFocusTracker, FOCUS_POLL_MS, focusKey } from './focus.mjs'
import { panelEntry, updatePanel } from './panel.mjs'
import { auditLogPath, watchRefreshRequests } from './refresh-requests.mjs'
import { collectSnapshot } from './snapshot.mjs'

// Entire writes its checkpoint data as an agent stops, so let it settle before reading.
const AGENT_SETTLE_MS = 3000

export default function activate(orca) {
  const notify = (notice, signal) =>
    orca.host.call('notifications.show', notice, { signal }).catch((error) => {
      console.error(`Notification failed: ${error.message}`)
    })

  const focus = createFocusTracker()
  let running = 0

  // One snapshot feeds both the report and the panel.
  async function refresh(signal, { onlyIfChanged = false } = {}) {
    running++
    try {
      const snapshot = await collectSnapshot(orca, { signal })
      if (snapshot.workspace) focus.markRead(focusKey(snapshot.workspace))
      const report = connectionReport(orca, snapshot)
      // Orca 1.4.245's command palette drops a command's result, so the report also goes to the plugin's Logs.
      console.log(report)
      let panel = 'no workspace'
      if (snapshot.workspace) panel = await updatePanel(panelEntry(snapshot), { onlyIfChanged }).catch((error) => `failed: ${error.message}`)
      if (panel !== 'updated') console.log(`Panel not updated: ${panel}`)
      return { report, panel }
    } finally {
      running--
    }
  }

  orca.commands.register('doctor', async (_args, { signal }) => {
    const { report } = await refresh(signal)
    await notify(connectionNotice(report), signal)
    return report
  })

  orca.commands.register('refresh', async (_args, { signal }) => {
    const { report, panel } = await refresh(signal)
    if (panel === 'installed copy') {
      await notify({ title: 'Entire: panel not updated', body: 'The panel updates only when Orca runs this plugin from a Development folder.' }, signal)
    } else if (panel !== 'updated') {
      await notify({ title: 'Entire: panel not updated', body: `${panel}\n${report.split('\n').slice(1).join('\n')}`.slice(0, 1000) }, signal)
    }
    return `Panel ${panel}`
  })

  // Background refreshes run one at a time, and a request that arrives while one waits joins it. The
  // joined refresh skips an unchanged write only if every request in it allowed that.
  let timer = null
  let queue = Promise.resolve()
  let waiting = false
  let quiet = true
  function queueRefresh(delayMs, { onlyIfChanged = false } = {}) {
    quiet &&= onlyIfChanged
    clearTimeout(timer)
    timer = setTimeout(() => {
      timer = null
      if (waiting) return
      waiting = true
      queue = queue
        .then(() => {
          waiting = false
          const options = { onlyIfChanged: quiet }
          quiet = true
          return refresh(undefined, options)
        })
        .catch((error) => console.error(`Refresh failed: ${error.message}`))
    }, delayMs)
  }

  // An agent finishing is when Entire has new checkpoints and sessions to show.
  orca.events.on('agent.status.changed', (event) => {
    if ((event.mainAgent?.state ?? event.state) === 'done') queueRefresh(AGENT_SETTLE_MS, { onlyIfChanged: true })
  })

  // The panel's refresh button reaches the worker through Orca's audit log, while the worker runs.
  const auditLog = auditLogPath()
  if (auditLog) watchRefreshRequests(auditLog, `plugin:${manifest.publisher}.${manifest.id}`, () => queueRefresh(0))

  // Read the focused workspace when focus moves to it and every few minutes after. The poll is also a
  // host call, which keeps Orca from stopping the worker as idle, so ↻ keeps working until Orca quits.
  // A refresh already running or scheduled reads the focused workspace anyway. After a switch the
  // panel shows "Checking…" until it is rewritten, so only the timed read may skip an unchanged write.
  setInterval(() => {
    orca.host.call('workspace.readContext', {}).then(
      (context) => {
        if (running || waiting || timer) return
        const reason = focus.dueRead(contextKey(context))
        if (!reason) return
        console.log(`Checking Entire for ${context.displayName} on ${context.branch} (${reason})`)
        queueRefresh(0, { onlyIfChanged: reason === 'timer' })
      },
      () => {}
    )
  }, FOCUS_POLL_MS).unref()
}

